let _markdown = "\n\n<Installation name=\"banner\" />\n\nUsage [#usage]\n\n<FeedbackBlock id=\"9ee4532acaf187f5\" body=\"Put the element at the top of your root layout, you can use it for displaying announcements.\">\n  Put the element at the top of your root layout, you can use it for displaying announcements.\n</FeedbackBlock>\n\n```tsx\nimport { Banner } from 'fumadocs-ui/components/banner';\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"en\">\n      <body>\n        <Banner>Hello World</Banner>\n        {children}\n      </body>\n    </html>\n  );\n}\n```\n\nVariant [#variant]\n\n<FeedbackBlock id=\"cd645a67f37b3233\" body=\"Change the default variant.\">\n  Change the default variant.\n</FeedbackBlock>\n\n```tsx\nimport { Banner } from 'fumadocs-ui/components/banner';\n\n<Banner variant=\"rainbow\">Hello World</Banner>;\n\n// customise colors\n<Banner\n  variant=\"rainbow\"\n  rainbowColors={[\n    'rgba(255,100,0, 0.5)',\n    'rgba(255,100,0, 0.5)',\n    'transparent',\n    'rgba(255,100,0, 0.5)',\n    'transparent',\n    'rgba(255,100,0, 0.5)',\n    'transparent',\n  ]}\n>\n  Hello World\n</Banner>;\n```\n\nChange Layout [#change-layout]\n\n<FeedbackBlock\n  id=\"e91afbb8b49c58aa\"\n  body=\"By default, the banner uses a style tag to modify Fumadocs layouts (e.g. reduce the sidebar height).\nYou can disable it with:\"\n>\n  By default, the banner uses a `style` tag to modify Fumadocs layouts (e.g. reduce the sidebar height).\n  You can disable it with:\n</FeedbackBlock>\n\n```tsx\nimport { Banner } from 'fumadocs-ui/components/banner';\n\n<Banner changeLayout={false}>Hello World</Banner>;\n```\n\nClose [#close]\n\n<FeedbackBlock id=\"bfda16c0314c7e05\" body=\"To allow users to close the banner, give the banner an ID.\">\n  To allow users to close the banner, give the banner an ID.\n</FeedbackBlock>\n\n```tsx\nimport { Banner } from 'fumadocs-ui/components/banner';\n\n<Banner id=\"hello-world\">Hello World</Banner>;\n```\n\n<FeedbackBlock id=\"2ca22616df629a16\" body=\"The state will be automatically persisted.\">\n  The state will be automatically persisted.\n</FeedbackBlock>\n";
